Code
muni_mc_sums |&gt; 
  left_join(nicknames) |&gt;
  filter(major_class_code == 2) |&gt; 
  group_by(year, Triad) |&gt;
  summarize(zerodollar_count = sum(zero_bills)) |&gt; 
  ggplot(aes(x=year, y = zerodollar_count, fill = Triad)) + 
  geom_bar(position = "stack", stat = "identity") + theme_minimal()+
  theme(legend.position = "top")+
  labs(title = element_text("Number of $0 Taxbills"), xlab = NULL,) +
  scale_y_continuous(labels = scales::comma, limits = c(0, 41000), name = "")





Figure 1.8: Number of tax bills that were $0 shown here is different than the value shown in the exemption report. This is due to missing disabled veteran exemption amounts that were not identified when writing the original report.

